import{_ as o,c as i,o as e,ah as t}from"./chunks/framework.BkHe6ehV.js";const r="/images/papers/2604-03144/figure-4.png",n="/images/papers/2604-03144/figure-5.svg",s="/images/papers/2603-16790/figure-3.png",c="/images/papers/2603-16790/figure-6.svg",d="/images/papers/2603-16733/figure-2.svg",b=JSON.parse('{"title":"iQuest 系列","description":"","frontmatter":{"title":"iQuest 系列","date":"2026-09-21 12:00:00","create":"2026-09-21 12:00:00","categories":["iquest"],"tags":["iquest"],"readingStats":{"words":6713,"minutes":20,"images":5}},"headers":[],"relativePath":"posts/llm/industry/mainllm/18-iquest-series.md","filePath":"posts/llm/industry/mainllm/18-iquest-series.md","lastUpdated":null}'),a={name:"posts/llm/industry/mainllm/18-iquest-series.md"};function g(u,l,p,h,m,k){return e(),i("div",null,l[0]||(l[0]=[t('<h2 id="变化点" tabindex="-1">变化点 <a class="header-anchor" href="#变化点" aria-label="Permalink to &quot;变化点&quot;">​</a></h2><div class="custom-block tip"><div class="custom-block-title">2026</div><p><strong>2026.04 · <a href="#_2604-incoder-32b-thinking-ecot-icwm">InCoder-32B-Thinking</a></strong></p><ul><li>在 InCoder 上加入错误驱动 CoT，学习从工具报错中修正代码。</li><li>ICWM 预测工业执行反馈，扩展可用训练经验。</li></ul><p><strong>2026.03 · <a href="#_2603-incoder-32b-15t-工业执行验证sft">InCoder-32B</a></strong></p><ul><li>以工业语料预训练，结合长上下文 MidTrain 与执行验证 SFT。</li><li>覆盖编译、仿真等工业代码任务与工具链。</li></ul><p><strong>2026.03 · <a href="#_2603-iquest-coder-v1-code-flow-loopcoder">IQuest-Coder-V1</a></strong></p><ul><li>Code-Flow 引入代码演化信息，结合分阶段 MidTrain。</li><li>LoopCoder 通过重复计算扩展模型推理深度。</li></ul></div><p>InCoder 为北航、IQuest Research 等机构合作工作，在本页与 IQuest-Coder 一起记录；不是 Meta 早期同名 InCoder 系列。</p><h2 id="_2604-incoder-32b-thinking-ecot-icwm" tabindex="-1">(2604) InCoder-32B-Thinking (ECoT, ICWM) <a class="header-anchor" href="#_2604-incoder-32b-thinking-ecot-icwm" aria-label="Permalink to &quot;(2604) InCoder-32B-Thinking (ECoT, ICWM)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">InCoder-32B-Thinking 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2604.03144" target="_blank" rel="noreferrer">paper</a>、<a href="https://github.com/CSJianYang/Industrial-Coder" target="_blank" rel="noreferrer">code</a>、<a href="https://huggingface.co/Multilingual-Multimodal-NLP/IndustrialCoder" target="_blank" rel="noreferrer">model</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>工业代码需要理解硬件限制、编译诊断与执行结果；通用代码数据缺少完整的错误分析与修复过程。</li><li>真实 GPU、EDA 与仿真工具执行成本高，限制多轮纠错数据的规模。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>ECoT</strong>：DeepSeek-V3.2 根据真实执行日志反复修改代码，将报错、诊断与修复整理为 Thinking 数据。</li><li><strong>ICWM</strong>：学习 <code>环境描述 + 代码 → 执行反馈</code>，用反馈预测扩充纠错轨迹，再进行真实执行验证。</li><li><strong>Thinking 训练</strong>：在 InCoder-32B 基础上学习约 <code>540M tokens</code> 的推理数据；核心是执行反馈驱动的数据合成与监督训练。</li></ul><p><strong>模型效果（InCoder-32B → Thinking）</strong></p><ul><li>LiveCodeBench v5：<code>53.3 → 81.3</code>；EmbedCGen：<code>35.2 → 47.9</code>；SuperCoder 加速比：<code>1.30× → 3.93×</code>。</li><li>SWE-bench Verified：<code>74.8 → 70.4</code>；推理增强并未同步提高所有代码与 Agent 任务。</li></ul><p><strong>重要结论</strong></p><ul><li>真实错误能够形成具体的推理监督；不同工业任务需要的思考深度差异很大。</li><li>扩大 Thinking 数据改善多数工业指标，复杂 kernel 优化仍存在平台期。</li></ul><p><strong>核心贡献</strong></p><ul><li>将真实工业执行、错误驱动 CoT 与反馈预测结合，构建可扩展的工业代码推理数据链路。</li></ul><p><strong>未来方向</strong></p><ul><li>提高几何、硬件边界条件的反馈预测精度，并兼顾 Thinking 能力与通用 Agent 表现。</li></ul></div><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">问题背景</div><p><strong>硬件与工具链约束</strong></p><ul><li>CUDA 代码可能算法正确，却因 grid 维度、共享内存或调度方式而运行失败。</li><li>Verilog 需要同时满足仿真与综合要求；CAD 脚本需要生成有效几何体，而不只是通过 Python 语法检查。</li></ul><p><strong>训练数据缺口</strong></p><ul><li>最终正确代码无法说明错误原因，也缺少从执行日志定位问题的示范。</li><li>将每轮 <code>代码 → 工具反馈 → 原因分析 → 修改</code> 保留下来，才能监督具体的纠错策略。</li></ul></div><h3 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="执行反馈推理数据" tabindex="-1">执行反馈推理数据 <a class="header-anchor" href="#执行反馈推理数据" aria-label="Permalink to &quot;执行反馈推理数据&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">任务输入与执行后端</div><p><strong>任务输入</strong></p><ul><li>复用 InCoder-32B 的工业任务，将需求与运行环境一起输入生成模型。</li><li>Verilog 包含 testbench 与综合脚本；STM32 包含头文件、内存布局与 linker script。</li></ul><p><strong>领域提示与工具</strong></p><ul><li>按领域选择提示：GPU 关注线程与内存，RTL 关注组合路径与时钟，CAD 关注几何约束。</li><li>执行后端包括 <code>CUDA / Triton</code>、<code>Yosys / Icarus</code>、<code>Renode</code> 与 <code>CadQuery</code>。</li><li>返回执行状态、报错日志和必要的数值结果，区分编译失败、运行错误与测试通过。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">ECoT 生成过程</div><p><strong>轨迹生成</strong></p><ul><li><strong>初始生成</strong>：DeepSeek-V3.2 根据任务与环境生成推理过程和候选代码。</li><li><strong>真实执行</strong>：工具编译、运行或仿真候选代码，返回具体失败信息。</li><li><strong>反馈修复</strong>：将日志放回上下文，生成错误分析与下一版代码，最多进行 <code>4轮</code> 修正。</li><li><strong>结束条件</strong>：全部检查通过，或达到纠错预算。</li></ul><p><strong>训练内容</strong></p><ul><li>保留中间失败、诊断依据与修改过程，将多轮交互整理为连贯的 Thinking 示例。</li><li>对轨迹去重、清理无效文字并统一代码格式，形成真实执行数据 <code>D_real</code>。</li><li>例如 CUDA 启动失败：根据 grid 限制诊断索引方式，再改为合法的维度映射。</li></ul></div><h4 id="工业反馈预测模型" tabindex="-1">工业反馈预测模型 <a class="header-anchor" href="#工业反馈预测模型" aria-label="Permalink to &quot;工业反馈预测模型&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">ICWM 训练目标</div><p><strong>输入与输出</strong></p><ul><li>输入：环境描述、领域标记与当前代码；输出：执行状态、诊断信息或数值差异。</li><li>将真实轨迹拆成单轮执行记录，训练反馈预测模型。</li><li>统一模型覆盖多类工业后端，使用领域模板约束反馈格式。</li></ul><p><strong>两个模型角色</strong></p><ul><li><strong>ICWM</strong>：预测这段代码运行后会发生什么，用于扩充训练数据。</li><li><strong>InCoder-32B-Thinking</strong>：学习诊断与修复轨迹，最终负责生成工业代码。</li></ul></div><div class="custom-block important"><div class="custom-block-title">数据扩充链路</div><p><strong>生成与校准</strong></p><ul><li>使用 ICWM 的单次预测代替大量中间执行，驱动生成模型继续诊断、修改代码。</li><li>定期调用真实工具检查预测反馈，将偏差样本用于更新 ICWM。</li><li>最终 Coder 训练使用真实产生或真实验证过的轨迹，组合 <code>D_real</code> 与扩充数据。</li></ul><p><strong>典型错误</strong></p><ul><li>CAD 的几何退化可能只在内核执行时出现，例如相切圆柱产生零厚度边缘。</li><li>此时语法合理的代码仍可能失败，真实验证用于拦截反馈模型误判的成功样本。</li></ul></div><figure style="margin:24px 0;"><img src="'+r+'" alt="ECoT 与 ICWM 的数据闭环：真实后端产生纠错轨迹，再训练反馈预测模型扩展合成规模，并通过真实执行审计校准。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 4：</strong>ECoT 与 ICWM 的数据闭环：真实后端产生纠错轨迹，再训练反馈预测模型扩展合成规模，并通过真实执行审计校准。 <a href="https://arxiv.org/html/2604.03144v1#S2.F4" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="实验设置-thinking-数据与工业评测" tabindex="-1">实验设置（Thinking 数据与工业评测） <a class="header-anchor" href="#实验设置-thinking-数据与工业评测" aria-label="Permalink to &quot;实验设置（Thinking 数据与工业评测）&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>基础模型与训练数据</strong></p><ul><li>基础模型：<code>InCoder-32B</code>；数据生成教师：<code>DeepSeek-V3.2</code>。</li><li>Thinking 数据规模：<code>180M / 360M / 540M tokens</code>，比较不同训练规模的 checkpoint。</li><li>ECoT 最多 <code>4轮</code> 修正；反馈预测训练使用真实工具产生的单轮记录。</li></ul><p><strong>评测任务</strong></p><ul><li>通用代码：<code>14项</code> benchmark，覆盖生成、推理、SQL、SWE、Terminal 与 Tool Use。</li><li>工业代码：<code>9项</code> benchmark，覆盖芯片设计、GPU kernel、嵌入式、代码优化与 CAD。</li><li>区分编译成功、功能正确和性能优化，例如 CAD 编译率与几何 IoU 分别统计。</li></ul><p><strong>ICWM 对照实验</strong></p><ul><li>每个领域使用 <code>2000条</code> 留出的真实执行记录，对比预测反馈与工具结果。</li><li>同时检查单次执行结果和多轮轨迹的一致性。</li></ul></div><h3 id="关键结果-incoder-32b-thinking-ecot-icwm-sft" tabindex="-1">关键结果（InCoder-32B-Thinking，ECoT + ICWM SFT） <a class="header-anchor" href="#关键结果-incoder-32b-thinking-ecot-icwm-sft" aria-label="Permalink to &quot;关键结果（InCoder-32B-Thinking，ECoT + ICWM SFT）&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">代码推理与工业任务</div><p><strong>推理型任务提升明显</strong></p><ul><li>LiveCodeBench v5：<code>53.3 → 81.3</code>；v6：<code>49.1 → 77.1</code>，复杂解题受益于 Thinking 数据。</li><li>CruxEval 输出推理：<code>73.9 → 95.5</code>，执行语义推断能力同步改善。</li></ul><p><strong>工业收益集中在诊断与优化</strong></p><ul><li>EmbedCGen：<code>35.2 → 47.9</code>；VeriRepair：<code>80.0 → 83.3</code>，嵌入式生成与 RTL 修复有所改善。</li><li>SuperCoder 正确率：<code>91 → 93</code>，加速比：<code>1.30× → 3.93×</code>，收益不只体现在代码能否运行。</li><li>CAD 编译率：<code>82 → 84</code>，但几何 IoU：<code>53.5 → 48.6</code>；可执行与符合设计目标需要分别评估。</li></ul><p><strong>Agent 与部分代码任务存在回退</strong></p><ul><li>SWE-bench Verified：<code>74.8 → 70.4</code>；Terminal-Bench 2.0：<code>22.5 → 21.6</code>。</li><li>BIRD：<code>55.4 → 47.9</code>，说明工业推理增强没有自动转化为所有代码任务的收益。</li></ul></div><div class="custom-block note"><div class="custom-block-title">数据规模与反馈预测分析</div><p><strong>Thinking 数据规模</strong></p><ul><li>从 <code>180M</code> 增至 <code>540M tokens</code>，VeriScope：<code>61.8 → 75.4</code>；KernelBench L2：<code>16.0 → 38.0</code>。</li><li>KernelBench L3 保持 <code>12.0</code>，更难的优化任务需要更有针对性的策略与数据。</li></ul><p><strong>思考长度随任务变化</strong></p><ul><li>数据中 Agent 单步思考中位数为 <code>91字符</code>，GPU kernel 为约 <code>19K字符</code>。</li><li>Agent 推理分散在多轮交互中；kernel 单次修复需要更深入的硬件分析。</li></ul><p><strong>ICWM 预测质量</strong></p><ul><li>平均执行结果准确率 <code>96.7%</code>，轨迹一致率 <code>94.4%</code>；多轮使用会累积单步预测误差。</li><li>因此反馈预测适合扩大候选轨迹规模，真实执行仍负责最终质量控制。</li></ul></div><figure style="margin:24px 0;"><img src="'+n+'" alt="ICWM 反馈质量的两个层次：单轮标签是否一致，以及多轮纠错后的最终判定是否一致；两者不能互相替代。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 5：</strong>ICWM 反馈质量的两个层次：单轮标签是否一致，以及多轮纠错后的最终判定是否一致；两者不能互相替代。 <a href="https://arxiv.org/html/2604.03144v1#S4.F5" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="未来方向" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">后续问题（笔记整理）</div><p><strong>工业反馈精度</strong></p><ul><li>补充几何退化、硬件边界与低频工具报错，提高 ICWM 对关键失败模式的覆盖。</li><li>根据预测不确定性选择真实执行，减少无效校验，同时控制多轮误差积累。</li></ul><p><strong>能力平衡与训练数据</strong></p><ul><li>平衡工业 Thinking、SQL 与 SWE 数据，减少专项训练造成的能力回退。</li><li>为复杂 kernel 优化增加性能诊断与策略示范，避免仅增加同类轨迹数量。</li></ul></div><h2 id="_2603-incoder-32b-15t-工业执行验证sft" tabindex="-1">(2603) InCoder-32B (15T, 工业执行验证SFT) <a class="header-anchor" href="#_2603-incoder-32b-15t-工业执行验证sft" aria-label="Permalink to &quot;(2603) InCoder-32B (15T, 工业执行验证SFT)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">InCoder-32B 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2603.16790" target="_blank" rel="noreferrer">paper</a>、<a href="https://github.com/CSJianYang/Industrial-Coder" target="_blank" rel="noreferrer">code</a>、<a href="https://huggingface.co/Multilingual-Multimodal-NLP/IndustrialCoder" target="_blank" rel="noreferrer">model</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>通用代码语料偏向 Web 与应用开发，工业代码的硬件语义、时序约束和专用 API 覆盖不足。</li><li>工业任务还要求仿真、综合与性能验证；代码能编译，只是正确性的第一层。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>工业预训练</strong>：规则、FastText 与语义检索召回工业代码，结合技术手册与工具链资料，训练 <code>15T tokens</code>。</li><li><strong>MidTrain</strong>：<code>8K → 32K → 128K</code>，加入工业推理 QA、Agent 轨迹、commit 和工程附属文件。</li><li><strong>执行验证 SFT</strong>：构建 <code>2.5M</code> 样本，覆盖直接实现、缺陷修复与性能优化。</li><li><strong>验证环境</strong>：统一 RTL 仿真、GPU 执行、CAD 几何与嵌入式工具链，为合成数据提供真实反馈。</li></ul><p><strong>模型效果（32B Dense）</strong></p><ul><li>SWE-bench Verified：<code>74.8</code>；RealBench 模块 Func@1：<code>62.7</code>。</li><li>CAD-Coder 编译率 <code>82.0</code>、IoU <code>53.5</code>；KernelBench L2 <code>fast₁=36.0</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>工业专项数据与执行验证可以形成较强的领域能力；数据需要覆盖运行条件和诊断过程。</li><li>编译、功能与性能是不同层次；模型仍容易在稀有 API、硬件语义和速度优化上失败。</li></ul><p><strong>核心贡献</strong></p><ul><li>将多个工业代码领域纳入同一基模的预训练、MidTrain 与 SFT，形成完整的数据和训练路线。</li></ul><p><strong>未来方向</strong></p><ul><li>增加稀有工业 API 与硬件约束数据，加强验证反馈训练和低层性能推理。</li></ul></div><h3 id="问题背景-1" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-1" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">工业代码的训练缺口</div><p><strong>领域知识</strong></p><ul><li>Verilog、CUDA、Triton 与嵌入式代码在通用语料中占比低，部分低层代码难以靠文件后缀识别。</li><li>同一算法落到硬件后，还要处理位宽、时序、寄存器、内存布局与资源限制。</li></ul><p><strong>验证要求</strong></p><ul><li>RTL 需要 testbench 与综合工具；GPU kernel 需要数值验证和计时；CAD 需要检查几何体。</li><li>例如 CUDA 的 grid 维度超限会导致启动失败，需要调整线程映射，而不是修改数学公式。</li></ul></div><div class="custom-block note"><div class="custom-block-title">模型配置</div><p><strong>32B Dense Transformer</strong></p><ul><li><code>64层</code>，hidden size <code>5120</code>，FFN size <code>27648</code>；<code>40个</code> query heads 与 <code>8个</code> KV heads。</li><li>使用 GQA、SiLU 与 RoPE；词表 <code>76800</code>，最大上下文 <code>128K</code>。</li><li>训练路线：通用及工业预训练 → 工业 MidTrain → 执行验证 SFT。</li></ul></div><h3 id="核心方法-1" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-1" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="工业环境与预训练数据" tabindex="-1">工业环境与预训练数据 <a class="header-anchor" href="#工业环境与预训练数据" aria-label="Permalink to &quot;工业环境与预训练数据&quot;">​</a></h4><div class="custom-block tip"><div class="custom-block-title">工具链与验证信号</div><p><strong>芯片设计</strong></p><ul><li>Icarus / Verilator 负责 RTL 编译与行为仿真；Yosys 检查可综合性并生成面积、时序信息。</li><li>输入源代码与 testbench，输出编译状态、仿真结果和综合报告。</li></ul><p><strong>GPU 与嵌入式</strong></p><ul><li>CUDA / Triton 在 <code>A100</code> 上编译执行，检查数值结果，并通过 CUDA events 计时。</li><li>STM32F407 使用交叉编译器、CMSIS 与 linker script，随后进入 Renode 仿真。</li><li>仿真保留外设寄存器与中断行为，检查固件是否能完成目标操作。</li></ul><p><strong>CAD 与代码优化</strong></p><ul><li>CadQuery / OpenCascade 将脚本转换为实体，检查生成是否成功以及与参考几何的重合程度。</li><li>x86-64 优化同时检查语义等价与执行性能，避免只奖励形式上的代码改写。</li></ul></div><div class="custom-block note"><div class="custom-block-title">数据采集与质量控制</div><p><strong>工业代码召回</strong></p><ul><li><strong>规则召回</strong>：利用后缀、目录与关键词识别 Verilog、CUDA、HLS 等显式工业代码。</li><li><strong>分类召回</strong>：人工标注种子训练 FastText，补充规则没有命中的代码。</li><li><strong>语义召回</strong>：检索设备驱动与硬件相关 C/C++，覆盖语法接近普通应用的工业样本。</li><li>OCR 提取手册、技术书籍中的代码；补充厂商文档、论坛和工程报告。</li></ul><p><strong>清洗与增强</strong></p><ul><li>进行文件、近重复、仓库 fork 与跨来源去重，过滤无效样本。</li><li>统一格式，补充跨文件依赖、平台限制与函数/模块说明。</li><li>修改后的代码通过 AST 对比与重新编译，减少清洗引入的语义变化。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">AR 与 FIM</div><p><strong>训练目标</strong></p><ul><li>自回归目标学习完整代码分布；FIM 学习给定前后文补全中间代码。</li><li>样本从函数、单文件逐渐过渡到多文件与项目，增加依赖关系的复杂度。</li></ul><p><strong>数据配比</strong></p><ul><li>持续保留通用代码和文本，避免工业数据完全替代通用能力训练。</li><li>根据留出工业任务的表现调整采样权重，提高薄弱领域的覆盖。</li></ul></div><h4 id="工业-midtrain" tabindex="-1">工业 MidTrain <a class="header-anchor" href="#工业-midtrain" aria-label="Permalink to &quot;工业 MidTrain&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">工业知识转为训练样本</div><p><strong>工业推理 QA</strong></p><ul><li>由工程场景确定目标约束，再构造种子代码，生成根因分析、性能诊断与修改方案。</li><li>使用执行、静态分析和一致性检查过滤错误推理。</li><li>例如 GPU 访存优化：给定 kernel 与 profiling 信息，分析访存模式并提出改写。</li></ul><p><strong>真实工程上下文</strong></p><ul><li>Agent 轨迹记录 <code>Thought → Action → Observation</code>，学习从工具输出继续操作。</li><li>commit 关联开发意图、修改前代码与修改后代码，补充演进过程。</li><li>保留 testbench、时序约束、综合脚本、profiling 与内存检查日志。</li><li>FIM 按 AST 边界遮盖函数或代码块，避免截断 RTL always block 等完整结构。</li></ul></div><div class="custom-block important"><div class="custom-block-title">32K 与 128K 训练</div><p><strong>32K 阶段</strong></p><ul><li>重点训练完整模块、kernel 函数和 testbench，直接扩展到 <code>32K</code>。</li><li>数据比例：QA <code>40%</code>、轨迹 <code>20%</code>、commit <code>15%</code>、工程文件 <code>15%</code>、FIM <code>10%</code>。</li></ul><p><strong>128K 阶段</strong></p><ul><li>训练长调试过程、跨模块依赖与多文件重构，增加轨迹与 FIM 的占比。</li><li>前四分之一训练过程中，长于 <code>32K</code> 的样本比例由 <code>10%</code> 逐渐增至 <code>50%</code>。</li><li>回放 <code>5%–10%</code> 的上一阶段数据，保留文件级任务能力。</li><li>学习率重新启动后做 cosine decay，配合长样本逐步进入训练。</li></ul></div><h4 id="执行验证-sft" tabindex="-1">执行验证 SFT <a class="header-anchor" href="#执行验证-sft" aria-label="Permalink to &quot;执行验证 SFT&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">数据构建与反馈修复</div><p><strong>任务与候选生成</strong></p><ul><li>将需求、接口、目标平台、依赖和验证脚本统一为结构化任务。</li><li>候选来自参考实现改写、模板扰动、跨语言迁移、检索增强和强模型生成。</li><li>多种生成途径增加实现方式与优化方案的多样性。</li></ul><p><strong>验证与修复</strong></p><ul><li>每个候选进入相应的编译、仿真、测试与性能检查。</li><li>失败时保留报错、反例、波形差异或性能瓶颈，生成修改后的代码并再次验证。</li><li>训练材料包含失败尝试、反馈与修复结果，使模型学习具体的调试过程。</li></ul><p><strong>最终样本</strong></p><ul><li>按可执行性、重复运行稳定性与信息量筛选，降低简单重复样本权重。</li><li><strong>直接实现</strong>：需求到正确代码；<strong>缺陷修复</strong>：失败到修正；<strong>性能优化</strong>：正确代码到更优实现。</li><li>验证反馈用于构建与筛选 SFT 数据，这篇工作的主体路线是预训练、MidTrain 与 SFT。</li></ul></div><figure style="margin:24px 0;"><img src="'+s+'" alt="InCoder-32B 的三阶段训练：预训练整理语料，MidTrain 引入工业知识与长上下文，SFT 使用真实工业工具反馈。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 3：</strong>InCoder-32B 的三阶段训练：预训练整理语料，MidTrain 引入工业知识与长上下文，SFT 使用真实工业工具反馈。 <a href="https://arxiv.org/html/2603.16790v3#S1.F3" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="实验设置-15t预训练与工业sft" tabindex="-1">实验设置（15T预训练与工业SFT） <a class="header-anchor" href="#实验设置-15t预训练与工业sft" aria-label="Permalink to &quot;实验设置（15T预训练与工业SFT）&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>预训练</strong></p><ul><li><code>32B Dense</code> 从零训练；<code>4096张 GPU</code>；总量约 <code>15T tokens</code>。</li><li>学习率 <code>3e-4</code>，global batch size <code>2048</code>；目标为 AR 与 FIM。</li></ul><p><strong>MidTrain 与 SFT</strong></p><ul><li>上下文 <code>8K → 32K → 128K</code>；两阶段使用工业推理与工程轨迹数据。</li><li>SFT 构建 <code>2.5M</code> 样本，约 <code>4.9K步</code>，global batch size <code>512</code>。</li><li>数据规模分析比较 <code>83M / 167M / 250M tokens</code> 三个工业 SFT checkpoint。</li></ul><p><strong>评测任务与协议</strong></p><ul><li><code>14项</code> 通用代码 benchmark；<code>9项</code> 工业 benchmark，覆盖 RTL、GPU、嵌入式、代码优化与 CAD。</li><li>RealBench 分模块与系统任务，分别评估可综合性 <code>Syn@k</code> 和功能正确性 <code>Func@k</code>，<code>k=1/5</code>。</li><li>KernelBench <code>fast₁</code> 要求结果正确且快于参考实现；CAD 同时统计编译成功率与几何 IoU。</li></ul></div><h3 id="关键结果-incoder-32b-工业预训练-sft" tabindex="-1">关键结果（InCoder-32B，工业预训练 + SFT） <a class="header-anchor" href="#关键结果-incoder-32b-工业预训练-sft" aria-label="Permalink to &quot;关键结果（InCoder-32B，工业预训练 + SFT）&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">通用能力与领域收益</div><p><strong>通用代码仍有竞争力</strong></p><ul><li>SWE-bench Verified 达 <code>74.8</code>；LiveCodeBench v6 为 <code>49.1</code>；BFCL 为 <code>61.0</code>。</li><li>说明工业专项训练能够与通用编程能力共存，但代码推理仍弱于更强的 Thinking 模型。</li></ul><p><strong>工业优势集中在功能实现</strong></p><ul><li>RealBench 模块 <code>Syn@1=74.8</code>、<code>Func@1=62.7</code>，编译通过后仍有功能正确性的缺口。</li><li>CAD-Coder 编译率 <code>82.0</code>、IoU <code>53.5</code>；对照 Claude-Sonnet-4.6 为 <code>77.0 / 32.4</code>。</li><li>KernelBench L1/L2/L3 为 <code>22.2 / 36.0 / 14.0</code>，在报告所列对照中表现较强。</li></ul><p><strong>正确性与优化能力需要区分</strong></p><ul><li>SuperCoder 正确率 <code>91.0</code>，但加速比只有 <code>1.3×</code>，高正确率并不代表善于性能优化。</li><li>EmbedCGen 为 <code>35.2</code>，显著弱于部分更大模型，工业能力在不同领域之间仍不均衡。</li></ul></div><div class="custom-block note"><div class="custom-block-title">数据规模与错误分析</div><p><strong>工业 SFT 扩展</strong></p><ul><li>从 <code>83M</code> 增至 <code>250M tokens</code>，多数工业指标持续改善；少数验证子指标较早趋于饱和。</li><li>领域数据有效，但需要根据失败类型调整内容，而不只扩大样本数。</li></ul><p><strong>1882个失败案例</strong></p><ul><li>RealBench 失败多为语法与编译问题；EmbedCGen 常见缺失或错误的 HAL/CMSIS API。</li><li>VeriRepair 的失败中 <code>79%</code> 是编译通过但功能错误，单靠语法修复不足以解决任务。</li><li>KernelBench 失败中约 <code>33%</code> 是正确但不够快，需要显式学习硬件性能诊断。</li></ul></div><figure style="margin:24px 0;"><img src="'+c+'" alt="扩大工业 SFT 数据后的九类任务表现：比较各领域随数据量增加的变化，不把所有任务视为同一种扩展曲线。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 6：</strong>扩大工业 SFT 数据后的九类任务表现：比较各领域随数据量增加的变化，不把所有任务视为同一种扩展曲线。 <a href="https://arxiv.org/html/2603.16790v3#S6.F6" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="未来方向-1" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-1" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">工业代码能力改进</div><p><strong>数据与验证</strong></p><ul><li>补充低频工业 API、精确类型与硬件语义，减少链接错误、位宽错误和不合法配置。</li><li>将更丰富的仿真、反例与性能反馈用于训练，提高功能推理与低层优化能力。</li></ul><p><strong>任务难度与能力均衡（笔记整理）</strong></p><ul><li>从模块级生成扩展到完整系统和长调试流程，强化跨模块约束与长期状态管理。</li><li>分别跟踪可编译、功能正确与性能收益，避免单一成功率掩盖工业任务的真实瓶颈。</li></ul></div><h2 id="_2603-iquest-coder-v1-code-flow-loopcoder" tabindex="-1">(2603) IQuest-Coder-V1 (Code-Flow, LoopCoder) <a class="header-anchor" href="#_2603-iquest-coder-v1-code-flow-loopcoder" aria-label="Permalink to &quot;(2603) IQuest-Coder-V1 (Code-Flow, LoopCoder)&quot;">​</a></h2><p><strong>🌺 论文摘要</strong></p><div class="custom-block danger"><div class="custom-block-title">IQuest-Coder-V1 论文摘要</div><p><strong>参考链接</strong></p><ul><li><a href="https://www.alphaxiv.org/abs/2603.16733" target="_blank" rel="noreferrer">paper</a>。</li></ul><p><strong>问题背景</strong></p><ul><li>静态代码主要提供最终实现，缺少需求变化、修改过程与失败修复的监督。</li><li>长程 Code Agent 需要跨文件理解、持续规划与反馈纠错，同时受到部署参数规模限制。</li></ul><p><strong>核心方法</strong></p><ul><li><strong>Code-Flow</strong>：关联旧仓库、patch 与新仓库，将软件演进过程加入预训练。</li><li><strong>两阶段 MidTrain</strong>：<code>32K</code> 推理与 Agent 轨迹 → <code>128K</code> 仓库级上下文。</li><li><strong>双路线后训练</strong>：Thinking 与 Instruct 均采用 <code>SFT + RL</code>，分别侧重深度求解与日常指令任务。</li><li><strong>LoopCoder</strong>：同一组 Transformer 参数运行两轮，通过跨轮 attention 与门控增加计算深度。</li></ul><p><strong>模型效果</strong></p><ul><li><code>40B-Loop-Instruct</code>：SWE-bench Verified <code>76.2</code>、Terminal-Bench 2.0 <code>33.0</code>。</li><li><code>40B-Loop-Thinking</code>：LiveCodeBench v6 <code>81.1</code>；普通 <code>40B-Instruct</code> 的 FullStackBench 达 <code>71.4</code>。</li></ul><p><strong>重要结论</strong></p><ul><li>训练对象从代码文本扩展到修改与交互过程，有助于覆盖完整开发任务。</li><li>Thinking 与 Loop 的收益依任务而异，不能只按单一榜单选择模型。</li></ul><p><strong>核心贡献</strong></p><ul><li>提供代码演进训练、Agent MidTrain、双路线后训练与参数复用架构的完整 Code 模型系列。</li></ul><p><strong>未来方向</strong></p><ul><li>优化循环计算的延迟收益，并提升长任务中的恢复能力与跨任务稳定性。</li></ul></div><h3 id="问题背景-2" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景-2" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">静态代码与开发过程</div><p><strong>训练信息缺口</strong></p><ul><li>代码快照说明当前实现，但没有完整呈现修改意图、变更依赖与验证过程。</li><li>Code Agent 还需要根据命令输出和测试错误调整计划，不能只学习一次生成最终答案。</li></ul><p><strong>模型系列</strong></p><ul><li>Dense 模型覆盖 <code>7B / 14B / 40B</code>，另外提供 <code>40B-Loop</code> 参数复用版本。</li><li>开放不同训练阶段 checkpoint，用于研究 MidTrain 与后训练带来的能力变化。</li></ul></div><h3 id="核心方法-2" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法-2" aria-label="Permalink to &quot;核心方法&quot;">​</a></h3><h4 id="code-flow-与-midtrain" tabindex="-1">Code-Flow 与 MidTrain <a class="header-anchor" href="#code-flow-与-midtrain" aria-label="Permalink to &quot;Code-Flow 与 MidTrain&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">预训练数据</div><p><strong>质量筛选</strong></p><ul><li>通用语料以 Common Crawl 等来源为基础，进行清洗、近重复过滤与 benchmark 去污染。</li><li>为文本、代码和数学训练质量分类器，依据较大模型标注筛选高信息量数据。</li><li>使用 AST 检查代码结构，结合不同编程语言的相似性组织采样。</li></ul><p><strong>代码事实知识</strong></p><ul><li>引入 <code>66M条 CodeSimpleQA-Instruct</code>，补充明确、客观的技术事实问答。</li><li>重点覆盖可验证的代码知识，避免含糊、多解或容易随时间改变的问题。</li></ul><p><strong>代码补全</strong></p><ul><li>文件级 FIM 使用前缀与后缀预测中间内容；仓库级 FIM 额外提供相关文件上下文。</li><li>混合随机字符/行切分与 AST 切分，覆盖表达式、语句和函数等粒度。</li></ul></div><div class="custom-block important"><div class="custom-block-title">Code-Flow</div><p><strong>训练样本</strong></p><ul><li>构造 <code>(R_old, P, R_new)</code>：修改前仓库、patch、修改后仓库。</li><li>从项目生命周期中相对成熟的阶段选取起点，再寻找具有实际开发意义的后续变更。</li><li>保留变更的时间顺序与项目上下文，使模型学习修改前提、代码变化与结果之间的关系。</li></ul><p><strong>与静态快照的区别</strong></p><ul><li>快照提供“最终实现是什么”；状态转移进一步提供“哪些代码因修改而发生变化”。</li><li>例如接口变更同时涉及调用方、实现与测试，完整变更比孤立文件更能呈现依赖关系。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">推理、交互与仓库上下文</div><p><strong>32K 阶段</strong></p><ul><li>在高质量代码退火后加入数学、代码、逻辑 QA，学习拆解任务与一致性检查。</li><li>加入完整 Agent 轨迹：命令、日志、错误、测试结果与后续修改。</li><li>混合 commit 和文件/仓库 FIM，连接推理过程与代码操作。</li></ul><p><strong>128K 阶段</strong></p><ul><li>扩展到 <code>128K</code> 序列，学习长仓库、多文件依赖与持续调试过程。</li><li>延续推理、轨迹和补全数据类型，增加真正需要长上下文的仓库样本。</li><li>MidTrain 已经接触环境反馈，后训练再强化任务完成与行为选择。</li></ul></div><h4 id="循环共享架构" tabindex="-1">循环共享架构 <a class="header-anchor" href="#循环共享架构" aria-label="Permalink to &quot;循环共享架构&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">循环计算</div><p><strong>参数复用</strong></p><ul><li>同一组 Transformer blocks 固定执行 <code>2轮</code>，第二轮继续处理第一轮形成的表示。</li><li>模型仍为 <code>40B参数</code>；增加的是计算深度，不是新增一套独立权重。</li></ul><p><strong>第二轮 Attention</strong></p><ul><li><strong>跨轮读取</strong>：第二轮 query 访问第一轮产生的 KV，利用上一轮表示。</li><li><strong>轮内读取</strong>：读取第二轮中的前序 token，保留当前轮的因果依赖。</li><li>learned gate 根据 query 混合两路 attention 输出，调整跨轮信息与轮内信息的比例。</li></ul></div><div class="custom-block tip"><div class="custom-block-title">LoopCoder 训练基础设施</div><p><strong>计算与显存</strong></p><ul><li>融合 gated attention kernel，减少中间数据搬运。</li><li>使用 Context Parallelism，在设备之间传输 KV 分片，支持长上下文训练。</li></ul><p><strong>训练可靠性</strong></p><ul><li>确定性重算与 tensor fingerprint 检查静默硬件错误。</li><li>循环架构增加推理计算，参数占用与生成延迟需要分别评估。</li></ul></div><h4 id="sft-与多目标-rl" tabindex="-1">SFT 与多目标 RL <a class="header-anchor" href="#sft-与多目标-rl" aria-label="Permalink to &quot;SFT 与多目标 RL&quot;">​</a></h4><div class="custom-block note"><div class="custom-block-title">后训练数据</div><p><strong>任务覆盖</strong></p><ul><li>包含 API 调用、全栈开发、竞赛代码、SQL、代码编辑、Terminal、SWE 与 GUI Agent。</li><li>结合任务扰动、测试驱动合成、逆向构建和自动环境搭建生成候选样本。</li></ul><p><strong>验证与训练</strong></p><ul><li>客观任务使用沙箱执行与符号验证；主观任务结合规则、reward model 与多 Agent 评估。</li><li>使用 sequence packing 和跨样本 mask，提高利用率并隔离样本。</li><li>课程从基础指令逐步过渡到复杂与对抗样本，配合 cosine decay 和较长的低学习率阶段。</li></ul></div><div class="custom-block important"><div class="custom-block-title">多目标优化</div><p><strong>后训练分工</strong></p><ul><li><strong>Thinking</strong>：推理轨迹 SFT → reasoning RL，强调复杂代码求解。</li><li><strong>Instruct</strong>：通用与代码指令 SFT → instruction RL，强调协助与指令遵循。</li><li>使用 replay、动态数据混合与任务组合，减少专项训练对通用能力的影响。</li></ul><p><strong>代码 RL</strong></p><ul><li>竞赛代码采用 GRPO 与 Clip-Higher，以测试通过率提供奖励，不额外加入 KL penalty。</li><li>SWE 使用可扩展云端沙箱，Agent 多轮调用工具、修改代码并运行测试。</li><li>SWE 奖励结合测试通过与效率约束，支持并行 rollout。</li></ul></div><figure style="margin:24px 0;"><img src="'+d+'" alt="Code-Flow 训练全流程：代码演化数据、MidTrain 与后训练衔接；对照正文区分基础训练和不同产品分支。" loading="lazy" style="display:block;margin:12px auto;background:#fff;" width="100%"><figcaption style="font-size:0.9em;line-height:1.6;color:var(--vp-c-text-2);"><strong>原文图 2：</strong>Code-Flow 训练全流程：代码演化数据、MidTrain 与后训练衔接；对照正文区分基础训练和不同产品分支。 <a href="https://arxiv.org/html/2603.16733v1#S1.F2" target="_blank" rel="noreferrer">来源</a></figcaption></figure><h3 id="实验设置-多规模与双路线后训练" tabindex="-1">实验设置（多规模与双路线后训练） <a class="header-anchor" href="#实验设置-多规模与双路线后训练" aria-label="Permalink to &quot;实验设置（多规模与双路线后训练）&quot;">​</a></h3><div class="custom-block tip"><div class="custom-block-title">实验设置</div><p><strong>模型配置</strong></p><ul><li><code>7B / 14B / 40B</code> 分别使用 <code>14 / 28 / 80层</code>，hidden size 均为 <code>5120</code>。</li><li><code>40个</code> query heads、<code>8个</code> KV heads，GQA，词表 <code>76800</code>，最大上下文 <code>128K</code>。</li><li>比较 Base、Instruct、Thinking 及 Loop 版本，区分架构与后训练路线。</li></ul><p><strong>训练路线</strong></p><ul><li>通用及代码预训练 → 高质量代码退火 → <code>32K / 128K</code> MidTrain → SFT + RL。</li><li>训练数据包括代码事实、仓库状态转移、FIM、推理和 Agent 轨迹。</li></ul><p><strong>评测任务</strong></p><ul><li>Base：CrossCodeEval 跨文件补全，覆盖 Python、Java、TypeScript 和 C#。</li><li>后训练：EvalPlus、BigCodeBench、FullStackBench、LiveCodeBench、CruxEval、Mercury 与 SQL。</li><li>Agent：SWE-bench Verified、Terminal-Bench、Mind2Web、BFCL 与 τ-bench 系列。</li><li>安全性：同时评估有害请求拒绝与正常请求误拒绝，使用 Tulu 3 评测集合。</li></ul></div><h3 id="关键结果-iquest-coder-v1-sft-rl" tabindex="-1">关键结果（IQuest-Coder-V1，SFT + RL） <a class="header-anchor" href="#关键结果-iquest-coder-v1-sft-rl" aria-label="Permalink to &quot;关键结果（IQuest-Coder-V1，SFT + RL）&quot;">​</a></h3><div class="custom-block important"><div class="custom-block-title">Agent、推理与通用代码</div><p><strong>Loop-Instruct 的 Agent 能力</strong></p><ul><li><code>40B-Loop-Instruct</code> 的 SWE-bench Verified 为 <code>76.2</code>，普通 <code>40B-Instruct</code> 为 <code>70.4</code>。</li><li>Terminal-Bench 2.0 两者均为 <code>33.0</code>，Loop 的收益没有覆盖所有长程任务。</li><li>BFCL：<code>51.7 → 73.9</code>，工具调用能力也呈现明显差异。</li></ul><p><strong>Thinking 更侧重竞赛推理</strong></p><ul><li>普通 40B 在 LiveCodeBench v6 上，Instruct 为 <code>46.9</code>，Thinking 为 <code>77.7</code>。</li><li>Loop-Thinking 进一步达到 <code>81.1</code>，体现推理训练与额外计算的组合收益。</li><li>14B 的同一指标从 Instruct <code>40.0</code> 到 Thinking <code>66.3</code>，这一差异不只存在于最大模型。</li></ul><p><strong>常规开发任务需要独立比较</strong></p><ul><li>FullStackBench：普通 <code>40B-Instruct=71.4</code>，Loop-Instruct 为 <code>68.3</code>，Thinking 为 <code>54.8</code>。</li><li>BIRD：普通 Instruct <code>70.5</code>，Thinking <code>53.6</code>；较强的长推理不等于更好的 SQL 生成。</li><li>因此模型选择应同时看推理、交互、开发与效率，避免由单项峰值推断整体能力。</li></ul></div><h3 id="未来方向-2" tabindex="-1">未来方向 <a class="header-anchor" href="#未来方向-2" aria-label="Permalink to &quot;未来方向&quot;">​</a></h3><div class="custom-block warning"><div class="custom-block-title">后续问题（笔记整理）</div><p><strong>循环计算效率</strong></p><ul><li>比较相同显存、延迟与总计算预算下的 Loop 和普通模型，明确参数复用的适用场景。</li><li>探索按任务难度调整循环深度，减少简单任务的额外计算。</li></ul><p><strong>长期交互与训练配比</strong></p><ul><li>加强错误恢复、跨文件状态与长轨迹监督，改善 Terminal 等复杂交互任务。</li><li>平衡 Thinking 与常规开发数据，减少推理增强后 SQL、全栈任务的能力损失。</li></ul></div>',72)]))}const f=o(a,[["render",g]]);export{b as __pageData,f as default};
